import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static List<Integer> relativeSortArray(List<Integer> arr1, List<Integer> arr2) {
        // Create a map of element to its order in arr2
        Map<Integer, Integer> orderMap = new HashMap<>();
        for (int i = 0; i < arr2.size(); i++) {
            orderMap.put(arr2.get(i), i);
        }

        // Sort arr1 using custom comparator
        return arr1.stream()
            .sorted((a, b) -> {
                boolean aInArr2 = orderMap.containsKey(a);
                boolean bInArr2 = orderMap.containsKey(b);

                if (aInArr2 && bInArr2) {
                    return orderMap.get(a) - orderMap.get(b);
                } else if (aInArr2) {
                    return -1;
                } else if (bInArr2) {
                    return 1;
                } else {
                    return a - b;
                }
            })
            .collect(Collectors.toList());
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> arr1 = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        List<Integer> arr2 = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<Integer> res = relativeSortArray(arr1, arr2);
        System.out.println(res.stream().map(String::valueOf).collect(Collectors.joining(" ")));
    }
}
